bootforge/arrays-objects/arrays/array-ba.solution:
export function updateTodos(todos, action) {
  const inRange = action.index >= 0 && action.index < todos.length;
  if (action.type === 'add') {
    todos.push(action.text);
  } else if (action.type === 'remove' && inRange) {
    todos.splice(action.index, 1);
  } else if (action.type === 'replace' && inRange) {
    todos.splice(action.index, 1, action.text);
  }
  return todos;
}

