bootforge/arrays-objects/objects/object-.solution:
export function toQueryString(params) {
  const pairs = Object.entries(params)
    .filter(([, v]) => v != null)
    .map(([k, v]) => `${k}=${v}`);
  if (pairs.length === 0) return '';
  return '?' + pairs.join('&');
}

export function fromQueryString(qs) {
  const body = qs.startsWith('?') ? qs.slice(1) : qs;
  if (body === '') return {};
  return Object.fromEntries(body.split('&').map((pair) => pair.split('=')));
}

