    parsed = JSON.parse(text);
  } catch {
    return null;
  }
  if (typeof parsed !== 'object' || parsed === null) return null;
  if (parsed.v !== 1) return null;
  if (!Object.hasOwn(parsed, 'data')) return null;
  return parsed.data;
}

