export function averageByLevel(records) {
  const sums = {};
  const counts = {};
  for (const r of records) {
    sums[r.level] = (sums[r.level] ?? 0) + r.score;
    counts[r.level] = (counts[r.level] ?? 0) + 1;
  }
  const out = {};
  for (const level of Object.keys(sums)) {
    out[level] = sums[level] / counts[level];
  }
  return out;
}

