  // your code here
}

bootforge/arrays-objects/data-shaping/tr.solution:
export function salesReport(sales) {
  const regions = {};
  for (const s of sales) {
    if (!regions[s.region]) {
      regions[s.region] = { totalCents: 0, saleCount: 0, byProduct: {} };
    }
    const r = regions[s.region];
    r.totalCents += s.cents;
    r.saleCount += 1;
    r.byProduct[s.product] = (r.byProduct[s.product] ?? 0) + s.cents;
  }
  return Object.entries(regions)
    .map(([region, r]) => {
      const top = Object.entries(r.byProduct).sort(
        (a, b) => b[1] - a[1] || a[0].localeCompare(b[0])
      )[0];
      return {
        region,
        totalCents: r.totalCents,
        saleCount: r.saleCount,
        topProduct: top[0],
      };
    })
    .sort((a, b) => b.totalCents - a.totalCents || a.region.localeCompare(b.region));
}

