bootforge/arrays-objects/data-shaping/im.solution:
export function cartReducer(state, action) {
  switch (action.type) {
    case 'add': {
      const exists = state.items.some((i) => i.sku === action.sku);
      const items = exists
        ? state.items.map((i) =>
            i.sku === action.sku ? { ...i, qty: i.qty + 1 } : i
          )
        : [...state.items, { sku: action.sku, qty: 1 }];
      return { ...state, items };
    }
    case 'remove':
      return { ...state, items: state.items.filter((i) => i.sku !== action.sku) };
    case 'setCoupon':
      return { ...state, coupon: action.code };
    case 'clear':
      return { items: [], coupon: null };
    default:
      return state;
  }
}

