export function summarizeResponse(res) {
  if (res?.error) {
    return { ok: false, message: res.error.message ?? 'request failed' };
  }
  const name = res?.data?.user?.name ?? 'anonymous';
  const orders = res?.data?.user?.orders ?? [];
